// 过滤出评论里含 #vk-<任务ID> 或 #recur-<标识> 的交易。
// P3：仅跳过「已成功处理」的交易（sd.lastIds）；处理失败的不入列，下次轮询自动重试。
const sd = $workflow.staticData;
if (!sd.lastIds) sd.lastIds = [];
const body = $input.item.json || {};
const result = (body && body.result) || body || {};
const txs = Array.isArray(result) ? result : (result.items || []);
const out = [];
for (const tx of txs) {
  if (sd.lastIds.includes(tx.id)) continue; // 已成功处理 → 跳过
  const comment = (tx.comment || '').toString();
  const mv = comment.match(/#vk-(\d+)/);
  const mr = comment.match(/#recur-([^#\s]+)/);
  if (mv) {
    out.push({ json: { kind: 'vk', txId: tx.id, taskId: parseInt(mv[1], 10), comment: comment, amount: tx.sourceAmount, type: tx.type, time: tx.time } });
  } else if (mr) {
    out.push({ json: { kind: 'recur', txId: tx.id, token: '#recur-' + mr[1], comment: comment, amount: tx.sourceAmount, type: tx.type, time: tx.time } });
  }
}
return out;

