// P3+P4：处理成功后才记入 sd.lastIds（失败不记 → 重试）；并对同周期重复扣款做护栏。
return await (async () => {
const token = $json.token;
const txId = $json.txId;
const txTime = $json.time; // ezB 交易时间（unix 秒），用于 P4 判重
const comment = $json.comment || '';
const auth = 'Bearer ' + $vars.vikunja_token;
const base = 'http://vikunja:3456/api/v1';
try {
  let tasks = [];
  for (let page = 1; page <= 20; page++) {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: base + '/tasks?per_page=50&page=' + page,
      headers: { Authorization: auth, 'Content-Type': 'application/json' },
      json: true
    });
    const arr = Array.isArray(r) ? r : (r.tasks || []);
    if (arr.length === 0) break;
    tasks = tasks.concat(arr);
    if (arr.length < 50) break;
  }
  const matches = tasks.filter(t => {
    const labels = (t.labels || []).map(l => (l && l.title !== undefined ? l.title : l).toString());
    return !t.done && labels.includes('recur') && labels.includes(token);
  });
  if (matches.length !== 1) {
    return [{ json: { token, txId, found: false, count: matches.length, note: '未找到唯一未完成的 recur 任务（0 或多个），跳过，避免误勾' } }];
  }
  const taskId = matches[0].id;
  // P4 竞态护栏：本任务已有「已扣款」评论且记录的交易时间 >= 本次交易时间 → 本周期已处理，跳过
  try {
    const cResp = await this.helpers.httpRequest({
      method: 'GET',
      url: base + '/tasks/' + taskId + '/comments',
      headers: { Authorization: auth, 'Content-Type': 'application/json' },
      json: true
    });
    const comments = Array.isArray(cResp) ? cResp : (cResp.comments || []);
    const doneComment = comments.find(c => /by:ezB周期交易 已扣款/.test(c.comment || c.text || ''));
    if (doneComment) {
      const m = (doneComment.comment || doneComment.text || '').match(/时间[ =](\d+)/);
      const recordedTime = m ? parseInt(m[1], 10) : undefined;
      if (recordedTime !== undefined && txTime !== undefined && recordedTime >= txTime) {
        return [{ json: { token, txId, found: true, taskId, skipped: true, note: '本周期已由更早/同级交易扣款，跳过避免重复勾选' } }];
      }
    }
  } catch (e) { /* 评论读取失败不阻断主流程 */ }
  // 标记完成（v2.5.0 无 /tasks/{id}/done 端点，用 POST /tasks/{id} 置 done=true）
  await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/tasks/' + taskId,
    headers: { Authorization: auth, 'Content-Type': 'application/json' },
    json: true,
    body: { done: true }
  });
  // 回写评论（含交易时间，供 P4 护栏判重）
  await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/tasks/' + taskId + '/comments',
    headers: { Authorization: auth, 'Content-Type': 'application/json' },
    json: true,
    body: { comment: 'by:ezB周期交易 已扣款，任务自动勾选完成（交易ID ' + txId + (txTime ? ('，时间 ' + txTime) : '') + '）' }
  });
  // P3：仅成功后才记 lastIds（失败 catch 分支不记 → 下次重试）
  const sd = $workflow.staticData; if (!sd.lastIds) sd.lastIds = [];
  sd.lastIds.push(txId); sd.lastIds = sd.lastIds.slice(-200);
  return [{ json: { token, txId, found: true, taskId, done: true } }];
} catch (e) {
  return [{ json: { token, txId, found: false, error: (e && e.message) ? e.message : String(e) } }];
}
})();

// P3：vk 分支回写评论成功后，才把 txId 记入 sd.lastIds（失败不记 → 重试）。
// K（幂等护栏）：n8n 重启会清空内存中的 staticData.lastIds，故回写前先查本任务评论，
//    若已含本交易回执（含 "交易ID <txId>"）则跳过，避免重启后重复发评论（持久化于 Vikunja）。
const sd = $workflow.staticData; if (!sd.lastIds) sd.lastIds = [];
const auth = 'Bearer ' + $vars.vikunja_token;
const base = 'http://vikunja:3456/api/v1';
const txId = $json.txId;
try {
  const cResp = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/tasks/' + $json.taskId + '/comments',
    headers: { Authorization: auth, 'Content-Type': 'application/json' },
    json: true
  });
  const comments = Array.isArray(cResp) ? cResp : (cResp.comments || []);
  const re = new RegExp('交易ID\\s*' + String(txId));
  if (comments.some(c => re.test(c.comment || c.text || ''))) {
    sd.lastIds.push(txId); sd.lastIds = sd.lastIds.slice(-200);
    return [{ json: { ...$json, processed: true, skipped: true, note: '评论已存在，幂等跳过（重启后护栏）' } }];
  }
  await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/tasks/' + $json.taskId + '/comments',
    headers: { Authorization: auth, 'Content-Type': 'application/json' },
    json: true,
    body: { comment: '财务侧记录已更新：' + String($json.comment||'').slice(0,200) + '（交易ID ' + txId + '）' }
  });
  sd.lastIds.push(txId); sd.lastIds = sd.lastIds.slice(-200);
  return [{ json: { ...$json, processed: true } }];
} catch (e) {
  return [{ json: { ...$json, processed: false, error: (e && e.message) ? e.message : String(e) } }];
}
